// Generated from frontend/public/brand/logo.png — inlined as a base64 data URI
// so the PDF report templates can embed the real brand logo without needing
// any build-step asset copying (tsc only emits .js from .ts/.tsx into dist/,
// and the Docker image only copies dist/ — a loose .png file next to this
// code would silently vanish in production). Regenerate by re-running the
// one-off base64 encode if the logo ever changes.
export const LOGO_DATA_URI =
  'data:image/png;base64,';
